begin;

update public.spell_catalog set name_ru='Лунный плащ Алустриэль', effect_summary='До 1 минуты с концентрацией вокруг тебя сияет лунный свет в радиусе 20 футов. Ты и союзники в области получаете половинное укрытие и сопротивление холоду, электричеству и излучению. Пока эффект действует, ты можешь досрочно завершить его одним из двух способов: реакцией превратить проваленный спасбросок против Испуга, Захвата или Опутывания в успех либо действием восстановить себе или союзнику в области 4к10 + модификатор заклинательной характеристики хитов.', author_description='Сначала это мощный защитный купол, а когда становится совсем плохо — одноразовый аварийный выход или большое лечение.', author_comment='Лунный свет здесь работает и бронёй, и кнопкой «нет, всё-таки выжил».', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Использование Освобождения или Передышки немедленно завершает заклинание. Материальный фокус — лунный камень стоимостью 50+ зм.', casting_time='1 действие' where slug='alustriel-s-mooncloak' and source_kind='official';

update public.spell_catalog set name_ru='Управление ветрами', effect_summary='Берёшь под контроль воздух в видимом кубе 100 футов на срок до 1 часа с концентрацией. Можешь выбрать горизонтальные порывы, нисходящий поток или восходящий поток и действием менять режим. Порывы мешают дальнобойным атакам и движению против сильного ветра; нисходящий поток сбивает летящих существ ничком при провале спасброска Силы; восходящий поток вдвое уменьшает урон от падения и увеличивает вертикальные прыжки на 10 футов.', author_description='Не маленький порыв, а полноценное управление погодой внутри огромного куба.', author_comment='Когда у тебя сто футов управляемого ветра, спор о том, где лучше стоять лучнику, заканчивается быстро.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Действием можно сменить режим, приостановить ветер или запустить его снова.', casting_time='1 действие' where slug='control-winds' and source_kind='official';

update public.spell_catalog set name_ru='Создание штурвала спеллджаммера', effect_summary='Касаешься незанятого кресла Большого размера или меньше, удерживая кристальный жезл стоимостью не менее 5000 зм. Жезл расходуется, а кресло навсегда превращается в магический штурвал спеллджаммера.', author_description='Одно действие — и обычное кресло становится сердцем корабля, способного ходить по Дикому космосу и Астральному морю.', author_comment='Самая дорогая модернизация стула в истории мебели.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Кристальный жезл стоимостью 5000+ зм расходуется. Само заклинание создаёт предмет «Штурвал спеллджаммера» со всеми его отдельными свойствами.', casting_time='1 действие' where slug='create-spelljamming-helm' and source_kind='official';

update public.spell_catalog set name_ru='Пляска смерти', effect_summary='До пяти Маленьких или Средних трупов в пределах 60 футов поднимаются как скелеты или зомби на срок до 1 часа с концентрацией. Они получают бонус к атакам и урону, равный модификатору твоей заклинательной характеристики. Бонусным действием можешь отдавать одной или всей группе единый приказ; без приказов они защищаются от враждебных существ.', author_description='Быстрый временный отряд нежити: не на дни и не навсегда, зато прямо сейчас и сразу несколько.', author_comment='Некромантия становится особенно эффективной, когда поле боя уже предоставляет материалы.', upcast='За каждый уровень ячейки выше 5 можно поднять ещё два трупа.', notes='Требуется концентрация. После окончания заклинания поднятые тела снова становятся обычными трупами.', casting_time='1 действие' where slug='danse-macabre' and source_kind='official';

update public.spell_catalog set name_ru='Рассвет', effect_summary='Создаёшь цилиндр солнечного света радиусом 30 футов и высотой 40 футов в пределах 60 футов на срок до 1 минуты с концентрацией. При появлении и когда существо заканчивает ход внутри, оно делает спасбросок Телосложения: при провале получает 4к10 урона излучением, при успехе — половину. Бонусным действием цилиндр можно переместить до 60 футов.', author_description='Мобильный кусок настоящего рассвета: большая зона солнечного света, которую можно таскать по полю за врагами.', author_comment='Если вампир спросил, почему потолок вдруг стал рассветом, значит всё работает.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Свет считается солнечным. Материальный компонент — подвеска в форме солнца стоимостью 100+ зм.', casting_time='1 действие' where slug='dawn' and source_kind='official';

update public.spell_catalog set name_ru='Истощение', effect_summary='Тёмный жгут связывает тебя с существом в пределах 60 футов на срок до 1 минуты с концентрацией. Цель делает спасбросок Ловкости: при успехе получает 2к8 некротического урона и заклинание заканчивается; при провале получает 4к8, после чего каждым своим действием ты можешь автоматически наносить ей ещё 4к8. Каждый раз, когда заклинание наносит урон, ты восстанавливаешь хиты в размере половины нанесённого некротического урона.', author_description='Магический дренаж в чистом виде: пока связь держится, чужие хиты буквально превращаются в твои.', author_comment='Очень убедительная причина спрятаться за полной стеной.', upcast='Урон увеличивается на 1к8 за каждый уровень ячейки выше 5.', notes='Заклинание заканчивается, если ты тратишь действие на что-то другое, цель выходит за пределы дистанции или получает от тебя полное укрытие.', casting_time='1 действие' where slug='enervation' and source_kind='official';

update public.spell_catalog set name_ru='Дальний шаг', effect_summary='Бонусным действием телепортируешься на расстояние до 60 футов в видимое свободное пространство. Пока сохраняешь концентрацию до 1 минуты, можешь повторять такую телепортацию бонусным действием в каждый свой ход.', author_description='Один телепорт хорош. Телепорт каждый раунд в течение минуты — уже совершенно другой способ жить на поле боя.', author_comment='Шестьдесят футов становятся не дистанцией, а предложением.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Каждая последующая телепортация также расходует бонусное действие.', casting_time='1 бонусное действие' where slug='far-step' and source_kind='official';

update public.spell_catalog set name_ru='Священное оружие', effect_summary='Бонусным действием касаешься оружия и на срок до 1 часа с концентрацией делаешь его магическим и светящимся; каждое попадание этим оружием наносит дополнительно 2к8 урона излучением. Бонусным действием можно досрочно завершить заклинание вспышкой: выбранные видимые существа в пределах 30 футов делают спасбросок Телосложения, получая 4к8 урона излучением при провале и становясь Ослеплёнными на 1 минуту; при успехе получают половину без ослепления.', author_description='Долгоиграющий бафф оружия, который в нужный момент превращается в финальную световую гранату.', author_comment='Святость — это когда меч не только бьёт сильнее, но ещё и умеет красиво завершить контракт.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Ослеплённая цель повторяет спасбросок Телосложения в конце каждого своего хода. Вспышка немедленно завершает заклинание.', casting_time='1 бонусное действие' where slug='holy-weapon' and source_kind='official';

update public.spell_catalog set name_ru='Самосожжение', effect_summary='Одно видимое существо в пределах 90 футов делает спасбросок Ловкости. При провале получает 8к6 огненного урона и продолжает гореть до 1 минуты с концентрацией; при успехе получает половину урона и дальнейшего эффекта нет. В конце каждого своего хода горящая цель повторяет спасбросок: при провале получает 4к6 огненного урона, при успехе пламя гаснет и заклинание заканчивается.', author_description='Это не просто поджог, а магическое пламя, которое продолжает требовать спасброски, пока цель наконец его не победит.', author_comment='Если огонь нельзя потушить водой, пора начинать уважать слово «магический».', upcast='Не имеет отдельного усиления ячейкой более высокого уровня.', notes='Немагические способы не гасят пламя. Если урон этого заклинания убивает цель, тело превращается в пепел.', casting_time='1 действие' where slug='immolation' and source_kind='official';

update public.spell_catalog set name_ru='Инфернальный призыв', effect_summary='За 1 минуту призываешь одного дьявола с ПО 6 или ниже в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Дьявол не обязан быть дружелюбным: в начале каждого своего хода ты можешь попытаться отдать приказ, противопоставив проверку Харизмы его Проницательности. При успехе он выполняет команду; при провале начинает действовать по собственной воле.', author_description='Демонология через переговоры: ты вызываешь профессионального злодея и каждый раунд напоминаешь ему, кто здесь заказчик.', author_comment='Главная материальная компонента — не рубин. Главная компонента — самоуверенность.', upcast='Максимальный ПО призываемого дьявола увеличивается на 1 за каждый уровень ячейки выше 5.', notes='Если у тебя есть талисман конкретного дьявола, можно призвать именно его и он подчиняется командам без проверки. Требуется концентрация.', casting_time='1 минута' where slug='infernal-calling' and source_kind='official';

update public.spell_catalog set name_ru='Водоворот', effect_summary='Создаёшь на земле или воде цилиндр бурлящей воды радиусом 30 футов и глубиной 5 футов на срок до 1 минуты с концентрацией. Область — труднопроходимая местность. Существо, начинающее там ход, делает спасбросок Силы; при провале получает 6к6 дробящего урона и притягивается на 10 футов к центру.', author_description='Большая зона, которая одновременно замедляет, бьёт и методично собирает всех к середине.', author_comment='Водоворот — это когда карта боя сама начинает группировать врагов.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Область должна помещаться на поверхности земли или воды.', casting_time='1 действие' where slug='maelstrom' and source_kind='official';

update public.spell_catalog set name_ru='Поток негативной энергии', effect_summary='Живое существо в пределах 60 футов делает спасбросок Телосложения, получая 5к12 некротического урона при провале или половину при успехе. Если этот урон убивает гуманоида, в начале твоего следующего хода он поднимается зомби и атакует ближайшее существо. Если целью была нежить, вместо урона она получает 5к12 временных хитов.', author_description='Одно и то же заклинание либо почти высасывает жизнь, либо буквально кормит нежить той же самой энергией.', author_comment='Некротическая энергия — просто очень специфическая система питания.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Поднятый зомби не находится под твоим контролем. Нежить не совершает спасбросок и получает временные хиты вместо урона.', casting_time='1 действие' where slug='negative-energy-flood' and source_kind='official';

update public.spell_catalog set name_ru='Усиление навыка', effect_summary='Касаешься добровольного существа, уже владеющего выбранным навыком. До 1 часа с концентрацией оно удваивает бонус мастерства для проверок этого навыка.', author_description='Не учит новому — делает уже знакомое дело заметно профессиональнее. Идеально перед одной критически важной серией проверок.', author_comment='Когда владения мало, магия временно выдаёт уровень «я этим вообще-то занимаюсь профессионально».', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Нельзя выбрать навык, для которого цель уже удваивает бонус мастерства. Требуется концентрация.', casting_time='1 действие' where slug='skill-empowerment' and source_kind='official';

update public.spell_catalog set name_ru='Стихийное насыщение Сонгал', effect_summary='На срок до 1 минуты с концентрацией наполняешь себя силой джиннов: выбираешь кислоту, холод, огонь, электричество или звук и получаешь сопротивление выбранному типу; получаешь скорость полёта 30 футов и зависание; при сотворении и в начале каждого своего хода выпускаешь 15-футовую волну выбранной стихии. Выбранные тобой существа в области делают спасбросок Ловкости: при провале получают 2к6 выбранного стихийного урона и падают ничком, при успехе — половину без падения.', author_description='Одновременно защита, полёт и повторяющийся стихийный взрыв каждый ход. Очень насыщенный бафф для одного заклинания.', author_comment='Сонгал решила, что выбирать между полётом, сопротивлением и уроном скучно.', upcast='Обычное усиление ячейкой не меняет базовые параметры.', notes='Требуется концентрация. У заклинания есть отдельная круговая версия: она дольше сотворяется, может длиться до 10 минут и распространять эффект на дополнительных существ.', casting_time='1 действие' where slug='songal-s-elemental-suffusion' and source_kind='official';

update public.spell_catalog set name_ru='Удар стального ветра', effect_summary='Выбираешь до пяти существ, которых видишь в пределах 30 футов, и для каждого совершаешь отдельную рукопашную атаку заклинанием. При попадании цель получает 6к10 урона силовым полем. После всех атак можешь телепортироваться в свободное пространство в пределах 5 футов от одной из выбранных целей.', author_description='Пять мгновенных ударов и телепорт в конце — заклинание выглядит так, будто персонаж на секунду становится монтажной нарезкой из самурайского фильма.', author_comment='Если врагов пятеро, геометрия превращается в стиль.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Для каждой цели бросок атаки делается отдельно. Материальный компонент — оружие ближнего боя стоимостью не менее 1 см; оно не расходуется.', casting_time='1 действие' where slug='steel-wind-strike' and source_kind='official';

update public.spell_catalog set name_ru='Призыв небожителя', effect_summary='Призываешь небесного духа в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь форму Мстителя или Защитника, что меняет стиль боя и свойства статблока. Дух действует сразу после тебя и выполняет твои команды.', author_description='Небожитель по вызову: либо держится дальше и наказывает врагов, либо становится светящимся телохранителем рядом с группой.', author_comment='Поддержка высших сил, оформленная в виде отдельной инициативы.', upcast='При использовании ячейки выше 5 её уровень используется в характеристиках небесного духа, усиливая статблок.', notes='Требуется концентрация. Материальный фокус стоимостью 500+ зм не расходуется. Форма выбирается при сотворении.', casting_time='1 действие' where slug='summon-celestial' and source_kind='official';

update public.spell_catalog set name_ru='Призыв драконьего духа', effect_summary='Призываешь Большого драконьего духа в свободное пространство в пределах 60 футов на срок до 1 часа с концентрацией. Выбираешь драконью природу и один из доступных ей типов сопротивления; пока заклинание действует, ты тоже получаешь сопротивление выбранному типу. Дух летает, атакует когтями и использует 30-футовое дыхание, наносящее 2к6 выбранного им типа урона при провале спасброска Ловкости.', author_description='Это не полноценный древний дракон, но летать, дышать стихией и делиться сопротивлением он вполне умеет.', author_comment='Когда «приведи дракона» звучит слишком дорого, есть магическая аренда.', upcast='При использовании ячейки выше 5 её уровень усиливает КД, хиты, число атак и другие параметры статблока драконьего духа.', notes='Требуется концентрация. Материальный фокус стоимостью 500+ зм не расходуется. Выбранная драконья природа определяет доступные сопротивления и типы дыхания.', casting_time='1 действие' where slug='summon-draconic-spirit' and source_kind='official';

update public.spell_catalog set name_ru='Синаптический разряд', effect_summary='В выбранной точке в пределах 120 футов взрывается психическая энергия сферой радиусом 20 футов. Существа делают спасбросок Интеллекта, получая 8к6 психического урона при провале или половину при успехе. Провалившая цель на 1 минуту вычитает 1к6 из всех атак, проверок характеристик и спасбросков Телосложения для поддержания концентрации; в конце каждого хода она повторяет спасбросок Интеллекта, прекращая эффект при успехе.', author_description='Психический огненный шар, который после взрыва оставляет противникам очень плохую математику на целую минуту.', author_comment='Минус к6 — это когда мозг не просто болит, а начинает мешать бухгалтерии бросков.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Существа с Интеллектом 2 или ниже не подвержены заклинанию. Эффект помутнения не требует концентрации.', casting_time='1 действие' where slug='synaptic-static' and source_kind='official';

update public.spell_catalog set name_ru='Временной сдвиг', effect_summary='Реакцией, когда видимое существо в пределах 120 футов совершает атаку или начинает сотворять заклинание, заставляешь его сделать спасбросок Мудрости. При провале оно исчезает из текущего момента: атака промахивается или заклинание тратится впустую. В начале своего следующего хода цель возвращается в прежнее или ближайшее свободное пространство и не помнит воздействия.', author_description='Вместо того чтобы остановить атаку, ты на секунду убираешь самого атакующего из времени.', author_comment='Контрзаклинание для тех случаев, когда проще отменить человека, чем его действие.', upcast='За каждый уровень ячейки выше 5 можно выбрать ещё одну цель; все цели должны находиться не далее 30 футов друг от друга.', notes='Реакция срабатывает на атаку или начало сотворения заклинания. Исчезнувшая цель возвращается в начале своего следующего хода.', casting_time='1 реакция, когда видимое существо совершает атаку или начинает сотворять заклинание' where slug='temporal-shunt' and source_kind='official';

update public.spell_catalog set name_ru='Преобразование камня', effect_summary='Выбираешь область камня или грязи, помещающуюся в куб 40 футов, и навсегда преобразуешь её одним из двух способов. Камень в грязь: каждый фут движения по ней стоит 4 футов скорости; существа на земле, входящие в область или заканчивающие там ход, делают спасбросок Силы и при провале становятся Опутанными. Каменный потолок превращается в падающую грязь и наносит 4к8 дробящего урона при провале спасброска Ловкости. Грязь в камень: слой грязи или зыбучего песка глубиной до 10 футов становится мягким камнем; находящиеся внутри существа при провале спасброска Ловкости оказываются зажаты.', author_description='Один из тех редких спеллов, который меняет не цель, а саму архитектуру поля боя — причём надолго.', author_comment='Пятый уровень магии: земля наконец становится редактируемым файлом.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Опутанный в грязи может действием вытащить себя. Зажатый камнем освобождается успешной проверкой Силы Сл 20 или после разрушения 25 хитов окружающего камня.', casting_time='1 действие' where slug='transmute-rock' and source_kind='official';

update public.spell_catalog set name_ru='Стена света', effect_summary='Создаёшь стену сияния длиной до 60 футов, высотой 10 футов и толщиной 5 футов на срок до 10 минут с концентрацией. При появлении существа в её области делают спасбросок Телосложения: при провале получают 4к8 урона излучением и ослепляются на 1 минуту, при успехе получают половину без ослепления. Существо, заканчивающее ход внутри стены, также получает 4к8 урона. Действием можешь выпустить из стены луч по видимой цели в пределах 60 футов: дальнобойная атака заклинанием наносит 4к8 урона излучением, после чего длина стены уменьшается на 10 футов.', author_description='Стена одновременно освещает, жарит тех, кто через неё проходит, и постепенно превращается в запас дальнобойных лучей.', author_comment='Редкая стена, которую можно буквально разобрать на выстрелы.', upcast='Урон стены и лучей увеличивается на 1к8 за каждый уровень ячейки выше 5.', notes='Требуется концентрация. Ослеплённая цель повторяет спасбросок Телосложения в конце своих ходов. Когда длина стены уменьшается до 0, заклинание заканчивается.', casting_time='1 действие' where slug='wall-of-light' and source_kind='official';

update public.spell_catalog set name_ru='Гнев природы', effect_summary='На срок до 1 минуты с концентрацией оживляешь траву, деревья, корни и камни в кубе 60 футов. Трава и подлесок становятся труднопроходимыми для врагов. В начале каждого твоего хода враги в 10 футах от дерева делают спасбросок Ловкости или получают 4к6 рубящего урона. В конце каждого твоего хода одну наземную цель можно заставить пройти спасбросок Силы или стать Опутанной корнями. Бонусным действием можно метнуть свободный камень: дальнобойная атака заклинанием наносит 3к8 дробящего урона и при провале спасброска Силы сбивает цель с ног.', author_description='Локация перестаёт быть декорацией и целую минуту начинает воевать на твоей стороне.', author_comment='Когда друид говорит «лес поможет», это иногда означает буквально весь лес.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Опутанная корнями цель может действием сделать Силу (Атлетика) против Сл твоих заклинаний и освободиться.', casting_time='1 действие' where slug='wrath-of-nature' and source_kind='official';

commit;